import { 
  MeshStandardNodeMaterial 
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, BoxGeometry, ConeGeometry, PointLight, Mesh } = ctx.THREE;

  // Create a container group
  const group = new Group();

  // Keep track of resources to clean up
  const timelines = [];
  const materialsToDispose = [];
  const geometriesToDispose = [];

  // Define colors from visual spec
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  // 1. Stage Backdrop
  // To satisfy STAGE, never void: Create a subtle background plate
  const bgGeo = new BoxGeometry(7, 3, 0.1);
  geometriesToDispose.push(bgGeo);
  const bgMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.8,
    metalness: 0.1
  });
  materialsToDispose.push(bgMat);
  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.6);
  group.add(bgMesh);

  // 2. Light Rig
  // Rim light to highlight the geometry edges
  const rimLight = new PointLight(colors.accent, 1.2, 5);
  rimLight.position.set(0, 1.5, 0.5);
  group.add(rimLight);

  // Key light
  const keyLight = new PointLight(colors.paper, 1.0, 6);
  keyLight.position.set(-2, 2, 1);
  group.add(keyLight);

  // Decorative Elements: Thin machined rule with a center jewel
  // Left half of the line
  const ruleGeo = new BoxGeometry(3.0, 0.02, 0.02);
  geometriesToDispose.push(ruleGeo);
  const ruleMat = new MeshStandardNodeMaterial({
    color: colors.paper,
    roughness: 0.52,
    metalness: 0.55,
    tag: 'machined-rule'
  });
  materialsToDispose.push(ruleMat);

  const leftRule = new Mesh(ruleGeo, ruleMat);
  leftRule.position.set(-1.6, 0, 0);
  group.add(leftRule);

  // Right half of the line
  const rightRule = leftRule.clone();
  rightRule.position.set(1.6, 0, 0);
  group.add(rightRule);

  // Center Jewel (faceted double cone)
  const jewelGeo = new ConeGeometry(0.12, 0.25, 8);
  geometriesToDispose.push(jewelGeo);
  const jewelMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    roughness: 0.1,
    metalness: 0.55,
    emissive: colors.accent,
    emissiveIntensity: 0.8
  });
  materialsToDispose.push(jewelMat);

  const jewelUpper = new Mesh(jewelGeo, jewelMat);
  jewelUpper.rotation.x = 0;
  jewelUpper.position.set(0, 0, 0);

  const jewelLower = new Mesh(jewelGeo, jewelMat);
  jewelLower.rotation.x = Math.PI;
  jewelLower.position.set(0, 0, 0);

  const jewelGroup = new Group();
  jewelGroup.add(jewelUpper);
  jewelGroup.add(jewelLower);
  group.add(jewelGroup);

  // 3. Load GLB Subject Content
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl)
      .then((gltf) => {
        const model = gltf.scene;
        // Scale and orient appropriately
        model.scale.set(0.65, 0.65, 0.65);
        model.position.set(0, 0.1, 0.1);

        // Traverse to apply PBR parameters consistently
        model.traverse((child) => {
          if (child.isMesh && child.material) {
            child.material.roughness = Math.max(child.material.roughness || 0.5, 0.5);
            child.material.metalness = Math.min(child.material.metalness || 0.4, 0.55);
          }
        });

        group.add(model);
      })
      .catch((err) => {
        console.warn('Failed to load GLB mesh, fallback geometry active:', err);
      });
  }

  // 4. Interactive State Handlers
  const state = {
    hovered: false,
    pressed: false
  };

  group.userData.handlers = {
    pointerover: () => {
      state.hovered = true;

      // Subtle rise-in animation
      const tl = gsap.timeline();
      tl.to(group.position, {
        y: 0.7000000000000001 + 0.15,
        duration: 0.3,
        ease: 'power2.out'
      });
      tl.to(jewelGroup.rotation, {
        y: Math.PI,
        duration: 0.5,
        ease: 'power3.out'
      }, 0);
      timelines.push(tl);
    },

    pointerout: () => {
      state.hovered = false;

      const tl = gsap.timeline();
      tl.to(group.position, {
        y: 0.7000000000000001,
        duration: 0.4,
        ease: 'power2.out'
      });
      tl.to(jewelGroup.rotation, {
        y: 0,
        duration: 0.6,
        ease: 'power3.out'
      }, 0);
      timelines.push(tl);
    },

    pointerdown: () => {
      state.pressed = true;

      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: 0.95,
        y: 0.95,
        z: 0.95,
        duration: 0.12,
        ease: 'power2.out'
      });
      timelines.push(tl);
    },

    pointerup: () => {
      if (state.pressed) {
        state.pressed = false;

        const tl = gsap.timeline();
        tl.to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.4,
          ease: 'back.out(1.7)'
        });
        timelines.push(tl);

        // Emit configured interaction event
        ctx.emit('hub-home.select', {
          nodeId: config.id,
          timestamp: Date.now()
        });
      }
    }
  };

  // 5. Cleanup Method
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometriesToDispose.forEach(geo => geo.dispose());
    materialsToDispose.forEach(mat => mat.dispose());
  };

  return group;
}
